--
-- Table structure for table `memberconsumers`
--

DROP TABLE IF EXISTS `memberconsumers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `memberconsumers` (
  `id` int NOT NULL AUTO_INCREMENT,
  `AccountNumber` varchar(11) DEFAULT NULL,
  `Name` varchar(99) DEFAULT NULL,
  `Area` char(3) DEFAULT NULL,
  `Address` varchar(99) DEFAULT NULL,
  `Status` int DEFAULT '0',
  `ShuffleOrder` int DEFAULT NULL,
  `ConnectionStatus` int unsigned DEFAULT NULL,
  `EntryMode` varchar(45) NOT NULL DEFAULT 'FOR REGISTRATION' COMMENT 'PREREGISTRATION | REGISTRATION',
  `Year` int unsigned NOT NULL DEFAULT '2023',
  `Gender` varchar(45) NOT NULL DEFAULT '',
  `isPosted` int unsigned NOT NULL DEFAULT '0',
  `RateCode` varchar(45) NOT NULL DEFAULT '',
  `IsQualifiedForRaffle` tinyint NOT NULL DEFAULT '1',
  `IsSignatureAvailable` tinyint NOT NULL DEFAULT '0',
  `DateRegistered` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=470624 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

